import{_ as t,m as r,p as n,ac as o}from"./chunks/framework.B20rRf_H.js";const p=JSON.parse('{"title":"NetherNet Protocol","description":"NetherNet protocol for Bedrock.","frontmatter":{"title":"NetherNet Protocol","category":"Protocols","mentions":["theaddonn","bedrock-crustaceans"],"description":"NetherNet protocol for Bedrock."},"headers":[{"level":2,"title":"Implementations","slug":"implementations","link":"#implementations","children":[]}],"relativePath":"servers/nethernet.md","filePath":"servers/nethernet.md"}'),a={name:"servers/nethernet.md"};function i(d,e,s,h,l,c){return r(),n("div",null,[...e[0]||(e[0]=[o('<p>Minecraft Bedrock uses multiple different protocols under the hood, one of them is NetherNet. NetherNet is the main protocol used for xbox live sessions, and is based on web-rtc.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>NetherNet is quite new and not finished, it is not as well known and understood as RakNet is.</p></div><p>Since we do not know too much about NetherNet, I can only refer to the <a href="https://github.com/df-mc/nethernet-spec" target="_blank" rel="noreferrer">documentation made by df-mc</a>.</p><h2 id="implementations" tabindex="-1">Implementations <a class="header-anchor" href="#implementations" aria-label="Permalink to &quot;Implementations&quot;">​</a></h2><p>Not everything can be explained in great detail via documentation, that&#39;s why looking at existing implementations is very helpful. Here is list of NetherNet implementations</p><table tabindex="0"><thead><tr><th>Name</th><th>Description</th><th>Language</th></tr></thead><tbody><tr><td><a href="https://github.com/bedrock-crustaceans/nethernet" target="_blank" rel="noreferrer">bedrock-crustaceans/nethernet</a></td><td>NetherNet implementation in Rust</td><td>Rust</td></tr><tr><td><a href="https://github.com/df-mc/go-nethernet" target="_blank" rel="noreferrer">df-mc/go-nethernet</a></td><td>Go library implementing a basic version of the NetherNet protocol</td><td>Go</td></tr><tr><td><a href="https://github.com/PrismarineJS/node-nethernet" target="_blank" rel="noreferrer">PrismarineJS/node-nethernet</a></td><td>NetherNet implementation in NodeJS</td><td>JavaScript, TypeScript</td></tr><tr><td><a href="https://github.com/Amber-PM/NetherNet" target="_blank" rel="noreferrer">Amber-PM/NetherNet</a></td><td>NetherNet implementation in PHP</td><td>PHP</td></tr><tr><td><a href="https://github.com/Bedrock-Phanatics/nethernet-zig" target="_blank" rel="noreferrer">Bedrock-Phanatics/nethernet-zig</a></td><td>NetherNet implementation in Zig</td><td>Zig</td></tr><tr><td><a href="https://github.com/bedrock-v/nethernet" target="_blank" rel="noreferrer">bedrock-v/nethernet</a></td><td>NetherNet implementation in V</td><td>V</td></tr></tbody></table><p>This page is a WIP, feel free to contribute as it is still being worked on.</p>',7)])])}const f=t(a,[["render",i]]);export{p as __pageData,f as default};
